export function Fab({
  label = "{{label}}",
  corner = "{{corner}}",
  size = "{{size}}",
  bg = "{{bg}}",
  extended = {{extended}},
}) {
  const pos = {
    "bottom-right": { right: 16, bottom: 16 },
    "bottom-left": { left: 16, bottom: 16 },
    "top-right": { right: 16, top: 16 },
    "top-left": { left: 16, top: 16 },
  }[corner];
  const dim = size === "lg" ? 64 : 56;
  return (
    <div style={{ position: "relative", height: 220, border: "1px dashed rgba(36,20,48,.25)", overflow: "hidden" }}>
      <p style={{ margin: 14, font: "500 13px/1 system-ui, sans-serif", color: "rgba(36,20,48,.5)" }}>Page content</p>
      <button
        type="button"
        aria-label={label}
        style={{
          position: "absolute",
          ...pos,
          display: "inline-flex",
          alignItems: "center",
          justifyContent: "center",
          gap: 8,
          width: extended ? "auto" : dim,
          height: extended ? 52 : dim,
          padding: extended ? "0 22px 0 20px" : 0,
          borderRadius: 999,
          border: "none",
          background: bg,
          color: "#FAF7F2",
          cursor: "pointer",
          boxShadow: "0 6px 16px rgba(36,20,48,.3)",
        }}
      >
        <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
          <path d="M12 5v14M5 12h14" />
        </svg>
        {extended && <span style={{ font: "600 14px/1 system-ui, sans-serif", whiteSpace: "nowrap" }}>{label}</span>}
      </button>
    </div>
  );
}
